//! WP-1739: the SVE and SME ACLE builtins (`__builtin_sve_*`,
//! `__builtin_sme_*`) clang 22 and clang 19 lower, with how each one is
//! lowered (spec/landed/codegen/WP-810.md "Builtin aliases").
//!
//! The table (`sve_builtins.rs`) is generated by
//! `scripts/gen-sve-builtins.py` from the `-O0` IR clang 22 and clang 19
//! emit for one call of each builtin. A builtin's lowering is a *family*
//! (a recipe of IR operations with its types and intrinsics as slots)
//! filled with the row's types and intrinsics. The family text is
//! `;`-separated operations, each a space-separated list:
//! - `S ret params...`: the builtin's signature (`#`: an immediate);
//! - `D @k[.T...] ret params...`: declare intrinsic `k` of the row,
//!   mangled with the overload types `T`;
//! - `a k`: evaluate argument `k`;
//! - `c d values...`: call the `d`-th declared intrinsic;
//! - `ev v i`, `iv agg v i` (`i` a number or immediate `#k`), `ie vec elt
//!   i`, `ee vec i` (WP-1791), `sv a b mask` (a `T:Z` mask: a splat), `sel c t f`,
//!   `gep T base idx`, `zext|sext|trunc|bitcast v T`,
//!   `shl|mul|add[.nuw|.nsw] a b`, `icmp.ne a b`: the instructions;
//! - `r [v]`: the result.
//!
//! An operation's value is `%n` (the result of the `n`-th operation after
//! the `S` and `D` ones), `T:k` (a constant: an integer, `P` poison, `U`
//! undef or `Z` zeroinitializer) or `T#k[*s][+o]` (immediate argument `k`,
//! scaled and offset). A type is `$n` (the row's `n`-th type), `i32`,
//! `i64`, `p` or `void`; a row's types are abbreviated LLVM types (see
//! [`type_text`]).
//!
//! WP-1792, WP-1793: the checks clang's Sema applies to a call of each
//! builtin ([`checks`]: its required target features, its streaming mode,
//! the ZA and ZT0 state it uses, its integer-constant operands and their
//! value checks) are in `sve_checks.rs`, generated by the same script
//! (`--checks`) from the tables clang-tblgen builds clang with. Each row is
//! `name spec22 spec19`; a spec is `features:mode:state:ice:imms` with
//! `features` a line of `FEATURES`, `mode` one of `s` (streaming), `c`
//! (streaming-compatible), `v` (verified at run time: streaming or not,
//! by the caller's features), `n` (non-streaming) or `-` (unchecked),
//! `state` clang's `ArmSMEState` bits (ZA in bits 0-1, ZT0 in 2-3), `ice`
//! the `.`-separated operands that must be integer constants and `imms`
//! the `,`-separated `operand.kind.bits` checks (an `ImmCheckType` name
//! without `ImmCheck` and the element width).

use std::sync::OnceLock;

use crate::sve_builtins as t;
use crate::sve_checks as ck;

/// A builtin's lowering at one clang version.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Lowering {
    /// The family's operations.
    pub family: &'static str,
    /// The intrinsics, `,`-separated indexes for [`intrinsic`].
    pub intrinsics: &'static str,
    /// The types, `,`-separated indexes for [`type_text`].
    pub types: &'static str,
}

/// An intrinsic a family calls.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Intrinsic {
    /// The name without its overload suffixes (`llvm.aarch64.sve.ld1`).
    pub name: &'static str,
    /// Its function attributes for LLVM 22 then 19 (`None`: clang of that
    /// version never declares it).
    pub attrs: [Option<&'static str>; 2],
    /// Its parameters' attributes for LLVM 22 then 19, one character each:
    /// `.` none, `i` `immarg`, `c` `nocapture`.
    pub params: [&'static str; 2],
}

fn lines(s: &'static str) -> Vec<&'static str> {
    s.split('\n').collect()
}

fn rows() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::ROWS))
}

fn families() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::FAMILIES))
}

fn types() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::TYPES))
}

fn attr_sets() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::ATTRS))
}

fn bases() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(t::BASES))
}

/// The row of builtin `name` (`sve_svadd_s32_x`: the name without its
/// `__builtin_` prefix).
fn row(name: &str) -> Option<&'static str> {
    let rows = rows();
    let i = rows.binary_search_by(|r| r.split(' ').next().unwrap_or("").cmp(name)).ok()?;
    Some(rows[i])
}

fn lowering(spec: &'static str) -> Option<Lowering> {
    let mut it = spec.split(':');
    let f: usize = it.next()?.parse().ok()?;
    Some(Lowering { family: families().get(f)?, intrinsics: it.next()?, types: it.next()? })
}

/// How clang `version` (22 or later, else 19) lowers builtin `name`
/// (`__builtin_sve_svadd_s32_x`): `None` when that clang has no such SVE or
/// SME builtin (or kiln lacks one of its types: the FP8 ones).
pub fn lookup(name: &str, version: u32) -> Option<Lowering> {
    let r = row(name.strip_prefix("__builtin_")?)?;
    let mut it = r.split(' ').skip(1);
    let s22 = it.next()?;
    let s19 = it.next()?;
    let spec = match (version >= 22, s19) {
        (false, "-") => return None,
        (false, "=") | (true, _) => s22,
        (false, s) => s,
    };
    lowering(spec)
}

/// The number of builtins in the table, and of those clang 19 has.
pub fn counts() -> (usize, usize) {
    let r = rows();
    (r.len(), r.iter().filter(|r| !r.ends_with(" -")).count())
}

/// The abbreviated LLVM type `i`: `s<n><T>` `<vscale x n x T>`,
/// `v<n><T>` `<n x T>`, `{T,...}` a literal struct, `c`
/// `target("aarch64.svcount")`, `h` half, `bf` bfloat, `f` float, `d`
/// double, `p` ptr, `i<n>`, `void`.
pub fn type_text(i: usize) -> Option<&'static str> {
    types().get(i).copied()
}

/// Intrinsic `i` of the table.
pub fn intrinsic(i: usize) -> Option<Intrinsic> {
    let mut it = bases().get(i)?.split(' ');
    let name = it.next()?;
    let mut attrs = [None; 2];
    let mut params = [""; 2];
    for v in 0..2 {
        let a = it.next()?;
        let p = it.next()?;
        if a != "-" {
            attrs[v] = Some(*attr_sets().get(a.parse::<usize>().ok()?)?);
            params[v] = if p == "-" { "" } else { p };
        }
    }
    Some(Intrinsic { name, attrs, params })
}

/// The streaming mode a builtin needs (clang `SemaARM::ArmStreamingType`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Mode {
    /// Only from a streaming function (`ArmStreaming`).
    Streaming,
    /// From any function (`ArmStreamingCompatible`).
    Compatible,
    /// From a streaming or a non-streaming function, by which half of the
    /// `SVE|SME` feature expression the caller's features satisfy
    /// (`VerifyRuntimeMode`).
    VerifyRuntime,
    /// Only from a non-streaming function (`ArmNonStreaming`).
    NonStreaming,
}

/// The checks of one builtin call at one clang version (WP-1792,
/// WP-1793; clang `SemaARM::CheckSVEBuiltinFunctionCall` /
/// `CheckSMEBuiltinFunctionCall`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Checks {
    /// The required-feature expression (clang `getRequiredFeatures`:
    /// `,` and, `|` or, parentheses; see [`features_hold`]).
    pub features: &'static str,
    /// The streaming mode it needs (`None`: not checked).
    pub mode: Option<Mode>,
    /// Whether it uses ZA state (`ArmZAMask`).
    pub za: bool,
    /// Whether it uses ZT0 state (`ArmZT0Mask`).
    pub zt0: bool,
    ice: &'static str,
    imms: &'static str,
}

/// One immediate operand's check (clang's `ImmChecks` tuple).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ImmCheck {
    /// The operand.
    pub arg: usize,
    /// The `ImmCheckType` name without `ImmCheck` (`0_7`, `Extract`).
    pub kind: &'static str,
    /// The element width in bits.
    pub elt_bits: u32,
}

/// What an [`ImmCheck`] requires of the operand's value (clang
/// `SemaARM::CheckImmediateArg`, a 128-bit container).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ImmRule {
    /// In `[lo, hi]` (`BuiltinConstantArgRange`, `err_argument_invalid_range`).
    Range(i64, i64),
    /// In `[lo, hi]`, then a multiple of `m` (`BuiltinConstantArgMultiple`).
    RangeMultiple(i64, i64, i64),
    /// 90 or 270 (`err_rotation_argument_to_cadd`).
    Rot90Or270,
    /// 0, 90, 180 or 270 (`err_rotation_argument_to_cmla`).
    RotAll90,
}

impl ImmCheck {
    /// The rule of this check (`None`: a kind kiln does not know).
    pub fn rule(&self) -> Option<ImmRule> {
        let w = i64::from(self.elt_bits.max(1));
        let r = ImmRule::Range;
        Some(match self.kind {
            "Extract" => r(0, 2048 / w - 1),
            "Cvt" | "ShiftRight" => r(1, w),
            "ShiftRightNarrow" => r(1, w / 2),
            "ShiftLeft" => r(0, w - 1),
            "LaneIndex" => r(0, 128 / w - 1),
            "LaneIndexCompRotate" => r(0, 128 / (2 * w) - 1),
            "LaneIndexDot" => r(0, 128 / (4 * w) - 1),
            "ComplexRot90_270" => ImmRule::Rot90Or270,
            "ComplexRotAll90" => ImmRule::RotAll90,
            "2_4_Mul2" => ImmRule::RangeMultiple(2, 4, 2),
            k => {
                let (lo, hi) = k.split_once('_')?;
                r(lo.parse().ok()?, hi.parse().ok()?)
            }
        })
    }
}

impl Checks {
    /// The operands that must be integer constant expressions (clang's
    /// `I` prototype prefix, checked by `CheckBuiltinFunctionCall` before
    /// anything else).
    pub fn ice_args(&self) -> impl Iterator<Item = usize> + '_ {
        self.ice.split('.').filter_map(|s| s.parse().ok())
    }

    /// The immediate operands' checks, in clang's order.
    pub fn imm_checks(&self) -> impl Iterator<Item = ImmCheck> + '_ {
        self.imms.split(',').filter_map(|c| {
            let mut it = c.split('.');
            let arg = it.next()?.parse().ok()?;
            let kind = it.next()?;
            let elt_bits = it.next()?.parse().ok()?;
            Some(ImmCheck { arg, kind, elt_bits })
        })
    }
}

fn check_rows() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(ck::CHECKS))
}

fn feature_lines() -> &'static [&'static str] {
    static R: OnceLock<Vec<&'static str>> = OnceLock::new();
    R.get_or_init(|| lines(ck::FEATURES))
}

/// The checks clang `version` (22 or later, else 19) applies to a call of
/// builtin `name` (`__builtin_sve_svext_s8`); `None` when that clang has
/// no such builtin.
pub fn checks(name: &str, version: u32) -> Option<Checks> {
    let name = name.strip_prefix("__builtin_")?;
    let rows = check_rows();
    let i = rows.binary_search_by(|r| r.split(' ').next().unwrap_or("").cmp(name)).ok()?;
    let mut it = rows[i].split(' ').skip(1);
    let s22 = it.next()?;
    let s19 = it.next()?;
    let spec = match (version >= 22, s19) {
        (true, _) | (false, "=") => s22,
        (false, s) => s,
    };
    if spec == "-" {
        return None;
    }
    let mut f = spec.splitn(5, ':');
    let features = feature_lines().get(f.next()?.parse::<usize>().ok()?)?;
    let mode = match f.next()? {
        "s" => Some(Mode::Streaming),
        "c" => Some(Mode::Compatible),
        "v" => Some(Mode::VerifyRuntime),
        "n" => Some(Mode::NonStreaming),
        _ => None,
    };
    let state: u32 = f.next()?.parse().ok()?;
    Some(Checks {
        features,
        mode,
        za: state & 0b0011 != 0,
        zt0: state & 0b1100 != 0,
        ice: f.next()?,
        imms: f.next()?,
    })
}

/// Whether the required-feature expression `list` holds for the features
/// `on` accepts (clang `TargetFeatures::hasRequiredFeatures`: `|` binds
/// loosest, then `,`; a parenthesized group is an operand). An empty
/// expression holds (`Builtin::evaluateRequiredTargetFeatures`).
pub fn features_hold(list: &str, on: &dyn Fn(&str) -> bool) -> bool {
    if list.is_empty() {
        return true;
    }
    let mut rest = list;
    let mut has = false;
    while !has && !rest.is_empty() {
        (has, rest) = and_features(rest, on);
    }
    has
}

/// clang `TargetFeatures::getAndFeatures`: the first `,`-joined term of
/// `list` (up to a top-level `|`) and what follows it.
fn and_features<'a>(list: &'a str, on: &dyn Fn(&str) -> bool) -> (bool, &'a str) {
    let mut depth = 0u32;
    let mut has = true;
    let mut start = 0;
    for (i, c) in list.bytes().enumerate() {
        match c {
            b'(' => {
                if depth == 0 {
                    start = i + 1;
                }
                depth += 1;
            }
            b')' | b'|' | b',' => {
                if c == b')' {
                    depth = depth.saturating_sub(1);
                }
                if depth == 0 {
                    if has && i != start {
                        let f = list.get(start..i).unwrap_or("");
                        has = if c == b')' { features_hold(f, on) } else { on(f) };
                    }
                    start = i + 1;
                    if c == b'|' {
                        return (has, list.get(start..).unwrap_or(""));
                    }
                }
            }
            _ => {}
        }
    }
    if has && start != list.len() {
        has = on(list.get(start..).unwrap_or(""));
    }
    (has, "")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn semantic_checks() {
        let ext = checks("__builtin_sve_svext_s8", 22).unwrap_or_else(|| panic!("svext_s8"));
        assert_eq!(ext.mode, Some(Mode::VerifyRuntime));
        assert_eq!(ext.ice_args().collect::<Vec<_>>(), [2]);
        let c: Vec<ImmCheck> = ext.imm_checks().collect();
        assert_eq!(c, [ImmCheck { arg: 2, kind: "Extract", elt_bits: 8 }]);
        assert_eq!(c[0].rule(), Some(ImmRule::Range(0, 255)));
        let ld = checks("__builtin_sme_svld1_hor_za8", 19).unwrap_or_else(|| panic!("ld1"));
        assert!(ld.za && !ld.zt0);
        assert_eq!(ld.mode, Some(Mode::Streaming));
        assert!(checks("__builtin_sve_svbogus", 22).is_none());
        // Every check of every row has a rule, and every builtin the
        // lowering table has has its checks.
        for r in check_rows() {
            let name = format!("__builtin_{}", r.split(' ').next().unwrap_or(""));
            for v in [22, 19] {
                if let Some(c) = checks(&name, v) {
                    assert!(c.imm_checks().all(|k| k.rule().is_some()), "{r}");
                }
            }
        }
        for r in rows() {
            let name = format!("__builtin_{}", r.split(' ').next().unwrap_or(""));
            assert!(checks(&name, 22).is_some(), "{name}");
            assert_eq!(checks(&name, 19).is_some(), lookup(&name, 19).is_some(), "{name}");
        }
    }

    #[test]
    fn feature_expressions() {
        let on = |set: &'static [&'static str]| move |f: &str| set.contains(&f);
        let hold = |l: &str, set: &'static [&'static str]| features_hold(l, &on(set));
        assert!(hold("sve", &["sve"]));
        assert!(!hold("sve,bf16", &["sve"]));
        assert!(hold("sve,bf16", &["sve", "bf16"]));
        assert!(hold("sve|sme", &["sme"]));
        // `|` binds loosest.
        assert!(hold("a,b|c", &["c"]));
        assert!(!hold("a,b|c", &["a"]));
        assert!(hold("(sve,(sve2|sme))|sme", &["sve", "sve2"]));
        assert!(!hold("(sve,(sve2|sme))|sme", &["sve"]));
        assert!(hold("(sve,(sve2|sme))|sme", &["sme"]));
        assert!(hold("sve|(sme,sme2p2)", &["sme", "sme2p2"]));
        assert!(!hold("sve|(sme,sme2p2)", &["sme"]));
        assert!(hold("", &[]));
    }

    #[test]
    fn table() {
        let (all, in19) = counts();
        assert!(all > in19 && in19 > 8000, "{all} {in19}");
        let rows = rows();
        assert!(rows.windows(2).all(|w| w[0].split(' ').next() < w[1].split(' ').next()));
        for r in rows {
            let name = format!("__builtin_{}", r.split(' ').next().unwrap_or(""));
            let l = lookup(&name, 22).unwrap_or_else(|| panic!("{r}"));
            for i in l.intrinsics.split(',').filter(|s| !s.is_empty()) {
                assert!(intrinsic(i.parse().unwrap_or(usize::MAX)).is_some(), "{r}");
            }
            for i in l.types.split(',').filter(|s| !s.is_empty()) {
                assert!(type_text(i.parse().unwrap_or(usize::MAX)).is_some(), "{r}");
            }
            assert_eq!(lookup(&name, 19).is_some(), !r.ends_with(" -"), "{r}");
        }
        assert!(lookup("__builtin_sve_svadd_s32_x", 19).is_some());
        assert!(lookup("__builtin_sve_svbogus", 22).is_none());
    }
}
